import React, { useEffect, useState } from 'react';

const Ahorro = ({ userId }) => {
    const [saveData, setSaveData] = useState({});

    useEffect(() => {
        const fetchSaveData = async () => {
            try {
                const response = await fetch(`http://localhost:5000/api/forms/save/getSave/${userId}`);
                const result = await response.json();
                setSaveData(result);
            } catch (error) {
                console.error('Error fetching save data:', error);
            }
        };

        if (userId) {
            fetchSaveData();
        }
    }, [userId]);

    return (
        <div className="ahorro-container">
            <h1 className="ahorro-title">Ahorro</h1>
            <div className="ahorro-content">
                <h3>Datos Ahorro</h3>
                <p>¿Tiene Meta Específica?: {saveData.hasSpecificGoal ? 'Sí' : 'No'}</p>
                <p>Monto Objetivo: ${saveData.targetAmount}</p>
                <p>Ahorros Semanales: ${saveData.weeklySavings}</p>
            </div>
        </div>
    );
};

export default Ahorro;
